package com.codepilot1c.core.tools.development;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
import com.codepilot1c.core.edt.development.RuntimePreparationService;
@ToolMeta(name="edt_runtime_prepare",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtRuntimePrepareTool extends AbstractTool {
 public String getDescription(){return "Unified runtime preparation via edt.run op=prepare. action=prepare requires explicit project/base_uuid/intent/idempotency_key; current binding and native EQUAL are mandatory. If equality is stale/not ready, performs one native read-only refresh with conflicts deferred; NOT_EQUAL blocks setup, never triggers DB update. Auto selects Native for code/data, direct TestClient for supported UI with Python, Vanessa for scenarios/unsupported UI. Creates/reuses managed Python then starts one owned TestClient; Native requires verified ZIP/path+SHA256 and uses external host only. Records resource IDs BEFORE launch. Vanessa verifies an existing saved profile/manager/client; missing setup returns a blocker, never changes trust or installs extensions. No DB update, binding change, business actions, metadata host or arbitrary endpoint. Poll status by preparation_id or job via edt_operation_status. Same key returns original preparation; unknown/restarted starts are never replayed or switched. Ready is freshly verified, not a saved receipt. cleanup_preview then cleanup with exact plan_sha256 affects only resources created here, preserves borrowed Python/Vanessa, never deletes base/project. Partial cleanup keeps exact original resources for another preview. Missing native trust can leave awaiting_runtime: use the original host, do not start another preparation.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["prepare","status","cleanup_preview","cleanup"]},"project":{"type":"string"},"base_uuid":{"type":"string"},"intent":{"enum":["code","query","data","ui","scenario"]},"engine":{"enum":["auto","native","testclient","vanessa"]},"required_actions":{"type":"array","maxItems":16,"items":{"type":"string"}},"previous_state":{"enum":["completed","rejected","unsupported","outcome_unknown","running"]},"idempotency_key":{"type":"string","maxLength":256},"preparation_id":{"type":"string","pattern":"^prep-[a-f0-9]{64}$"},"native_path":{"type":"string"},"expected_native_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"profile_id":{"type":"string"},"client_kind":{"enum":["thin","thick"],"default":"thin"},"readiness_timeout_s":{"type":"integer","minimum":10,"maximum":180,"default":90},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """;}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{var a=new LinkedHashMap<>(p.getRaw());String action=p.requireString("action");a.remove("action");var s=RuntimePreparationService.workspace();Object r;
  if(action.equals("prepare"))r=s.prepare(a);
  else{Set<String> fields=action.equals("cleanup")?Set.of("preparation_id","expected_plan_sha256"):Set.of("preparation_id");if(!fields.containsAll(a.keySet()))throw new IllegalArgumentException("Field does not apply to action");String id=p.requireString("preparation_id");r=switch(action){case "status"->s.status(id);case "cleanup_preview"->s.cleanupPreview(id);case "cleanup"->{String hash=p.requireString("expected_plan_sha256");String job=BackgroundJobRegistry.getInstance().startJob("runtime-preparation-cleanup",()->new Gson().toJson(s.cleanup(id,hash)));yield Map.of("job_id",job,"preparation_id",id,"next_tool","edt_operation_status");}default->throw new IllegalArgumentException("Unknown preparation action");};}
  return CompletableFuture.completedFuture(ToolResult.success(new Gson().toJson(r)));
 }catch(Exception e){return CompletableFuture.completedFuture(ToolResult.failure("edt_runtime_prepare: "+e.getMessage()));}}
}
